type Store = Record<SettingScope, Map<string, unknown>>;
const stores = new Map<string, Store>();

const GLOBAL_FILE = "/Users/fake/.omp/agent/config.yml";

/** One store per project directory; the global scope is shared by all. */
const globalValues = new Map<string, unknown>([
  ["edit.fuzzyMatch", false],
  ["hindsight.apiToken", "hs-fake-3f2a-secret"],
]);

function storeFor(cwd: string | undefined): Store {
  const key = cwd ?? "";
  let found = stores.get(key);
  if (!found) {
    found = { global: globalValues, project: new Map() };
    stores.set(key, found);
  }
  return found;
}

/** One field of the request params, which arrive as `unknown` off the wire. */
function field(params: unknown, key: string): unknown {
  return typeof params === "object" && params !== null ? Reflect.get(params, key) : undefined;
}

function str(params: unknown, key: string): string | undefined {
  const v = field(params, key);
  return typeof v === "string" ? v : undefined;
}

function layer(values: Map<string, unknown>, def: Def): SettingLayer {
  if (!values.has(def.id)) return { set: false };
  return def.secret ? { set: true } : { set: true, value: values.get(def.id) };
}

function valueIn(store: Store, scope: SettingScope, def: Def): unknown {
  if (scope === "project" && store.project.has(def.id)) return store.project.get(def.id);
  return store.global.has(def.id) ? store.global.get(def.id) : def.default;
}

function entryOf(def: Def, store: Store, scope: SettingScope): SettingEntry {
  const source =
    scope === "project" && store.project.has(def.id)
      ? "project"
      : store.global.has(def.id)
        ? "global"
        : "default";
  const gate = def.unless;
  const open =
    !gate || valueIn(store, scope, DEFS.find((d) => d.id === gate.id) ?? def) === gate.equals;
  return {
    id: def.id,
    tab: def.tab,
    group: def.group,
    label: def.label,
    description: def.description,
    type: def.type,
    secret: def.secret === true,
    ...(def.unit ? { unit: def.unit } : {}),
    ...(def.options ? { options: def.options } : {}),
    ...(def.ordered ? { ordered: true } : {}),
    envActive: false,
    value: def.secret ? null : valueIn(store, scope, def),
    source,
    layers: {
      default: def.secret ? null : def.default,
      global: layer(store.global, def),
      project: layer(store.project, def),
    },
    ...(open ? {} : { disabledReason: gate?.reason ?? "unavailable" }),
  };
}

const entriesOf = (store: Store, scope: SettingScope) =>
  DEFS.map((def) => entryOf(def, store, scope));

/** `cwdOf` answers for a session id, like the real sidecar: the window never sends a directory. */
export function handleSettings(
  method: string,
  id: string,
  params: unknown,
  readOnly: boolean,
  cwdOf: (sessionId: string) => string | undefined,
): ResponseEnvelope | undefined {
  if (!method.startsWith("settings.")) return undefined;
  const scope = str(params, "scope") === "project" ? "project" : "global";
  const sessionId = str(params, "sessionId");
  const cwd = sessionId === undefined ? undefined : cwdOf(sessionId);
  if (scope === "project" && cwd === undefined) {
    return errorResponse(id, {
      code: "internal",
      message: "the project scope needs a session",
    });
  }
  const store = storeFor(cwd);
  const files = { global: GLOBAL_FILE, project: cwd ? `${cwd}/.omp/config.yml` : null };

  if (method === "settings.list") {
    return okResponse(id, { scope, tabs: TABS, entries: entriesOf(store, scope), files });
  }
  const def = DEFS.find((d) => d.id === str(params, "id"));
  if (!def) return errorResponse(id, { code: "invalid_request", message: "unknown setting" });

  if (method === "settings.reveal") {
    const stored = store[scope].get(def.id);
    return okResponse(id, { value: typeof stored === "string" ? stored : "" });
  }
  if (method !== "settings.set" && method !== "settings.reset") return undefined;
  if (readOnly) {
    return errorResponse(id, {
      code: "read_only",
      message: `${method} writes and the shared omp database is newer than this app supports`,
    });
  }
  const before = entriesOf(store, scope);
  if (method === "settings.set") {
    const value = field(params, "value");
    const refusal = def.check?.(value);
    if (refusal) return okResponse(id, { ok: false, message: refusal });
    store[scope].set(def.id, value);
  } else {
    store[scope].delete(def.id);
  }
  const after = entriesOf(store, scope);
  const entries = after.filter(
    (entry, i) => entry.id === def.id || JSON.stringify(entry) !== JSON.stringify(before[i]),
  );
  return okResponse(id, { ok: true, entries });
}
